1	/**
2	 * Everything the plugin decides, with nothing from the SDK in it.
3	 *
4	 * A key face is a function of what the plugin knows: whether it is
5	 * signed in, whether its socket is open, which runs are held, which is
6	 * pinned, and what that run last published. `reduce` moves the state on
7	 * one event at a time; the `*Face` functions read it. Keeping them pure
8	 * is what lets the twelve states a key can be in have a test each.
9	 */
10	
11	/**
12	 * What a deck may press, right now, in the pack's own words.
13	 *
14	 * Copied from `apps/web/src/run/offer.ts`: the plugin does not import
15	 * from `apps/web`, so this shape is mirrored rather than shared.
16	 */
17	export interface Offer {
18	  seq: number;
19	  primary: { id: "roll" | "carry-on" | "close" | "enter"; label: string; kind: string } | null;
20	  moves: Array<{ id: string; label: string }>;
21	  undo: { what: string } | null;
22	  /** Why a deck cannot press this, in words a key face can carry. */
23	  needsPage: string | null;
24	  presets: Array<{ kind: string; label: string; suggestions?: string[]; items?: number }>;
25	  /** The setups the run could hand out, empty where the run names no tool or is not live. */
26	  setups: Array<{ id: string; title: string }>;
27	}
28	
29	export type SessionState = "none" | "expired" | "ok";
30	export type SocketState = "closed" | "connecting" | "open";
31	export interface HeldRun {
32	  id: string;
33	  name?: string;
34	  packTitle?: string;
35	}
36	export interface Snapshot {
37	  /** The run as the server knows it, which is where the pack's id travels. */
38	  run?: { id?: string; packId?: string };
39	  unit?: number;
40	  words?: { unit: string };
41	  score?: { text: string };
42	  latest?: { text: string } | null;
43	  clocks?: Array<{ id: string; label: string; kind: "timer" | "stopwatch"; seconds: number | null; status: string; elapsedMs: number }>;
44	  standings?: Array<{ name: string; points: number; place: number }>;
45	  counters?: Array<{ id: string; label: string; value: number }>;
46	  resources?: Array<{ id: string; label: string; value: number; max: number | null }>;
47	  at?: string;
48	  offer?: Offer;
49	}
50	export interface DeckState {
51	  session: SessionState;
52	  /** Whether the streamer has switched the deck on. No socket while false. */
53	  on: boolean;
54	  /** Whether the last time it went off, it was the idle timer rather than a press. */
55	  idleOff: boolean;
56	  socket: SocketState;
57	  runs: HeldRun[];
58	  any: boolean;
59	  pinned: string | null;
60	  attached: string | null;
61	  snapshot: Snapshot | null;
62	  flash: { ref: string; ok: boolean; say?: string; until: number } | null;
63	}
64	/**
65	 * How a face is drawn, by what the key is for rather than by how it feels.
66	 *
67	 * `live` is a key that moves the run - Next, Roll, Press - and it is the
68	 * only one that takes the celadon edge. `undo` is the same lit face with
69	 * the kiln edge, because taking a result back is the consequence the
70	 * second accent is for. `readout` is a Metric key, which is a number
71	 * rather than a button: the app's own ground, a hairline, and lit ink.
72	 * `deck` is the furniture - Connect, Run, Open, Apply setup - lit, but
73	 * without an accent claiming it does something to the run. `dim` and
74	 * `refuse` are states rather than families and belong to every key.
75	 */
76	export type Tone = "live" | "dim" | "refuse" | "undo" | "readout" | "deck";
77	export interface Face {
78	  title: string;
79	  tone: Tone;
80	  when?: string;
81	  /** 0-1, set only for a running timer clock so a dial's indicator can draw it. */
82	  fraction?: number;
83	}
84	export type PressTarget = { kind: "roll" } | { kind: "move"; id: string } | { kind: "answer"; preset: string; value: string };
85	export type MetricField = "score" | "unit" | "clock" | "latest" | "leader" | { counter: string } | { resource: string };
86	export type DeckEvent =
87	  | { t: "session"; state: SessionState }
88	  | { t: "on"; on: boolean; idle?: boolean }
89	  | { t: "socket"; state: SocketState }
90	  | { t: "runs"; runs: HeldRun[]; any: boolean }
91	  | { t: "pin"; id: string | null }
92	  | { t: "snapshot"; snapshot: Snapshot }
93	  | { t: "drove"; ref: string; ok: boolean; say?: string; seq?: number }
94	  | { t: "tick" };
95	
96	const FLASH_MS = 3000;
97	
98	/** How long a connection that is holding nothing waits before closing itself. */
99	export const IDLE_OFF_MS = 30 * 60_000;
100	
101	export function initial(): DeckState {
102	  return {
103	    session: "none",
104	    on: false,
105	    idleOff: false,
106	    socket: "closed",
107	    runs: [],
108	    any: false,
109	    pinned: null,
110	    attached: null,
111	    snapshot: null,
112	    flash: null,
113	  };
114	}
115	
116	export function attachedRun(state: DeckState): string | null {
117	  if (state.pinned) return state.runs.some((r) => r.id === state.pinned) ? state.pinned : null;
118	  return state.runs.length === 1 ? state.runs[0]!.id : null;
119	}
120	
121	export function reduce(state: DeckState, event: DeckEvent, now: number): DeckState {
122	  switch (event.t) {
123	    case "session":
124	      return event.state === "ok" ? { ...state, session: "ok" } : { ...initial(), session: event.state, pinned: state.pinned };
125	    case "on":
126	      // Going off is a full stop: no socket, nothing held, nothing to draw
127	      // a number from. The pin is a preference, not a holding, and stays.
128	      return event.on
129	        ? { ...state, on: true, idleOff: false }
130	        : { ...state, on: false, idleOff: event.idle === true, socket: "closed", runs: [], attached: null, snapshot: null };
131	    case "socket":
132	      return event.state === "open"
133	        ? { ...state, socket: "open" }
134	        : { ...state, socket: event.state, runs: [], attached: null, snapshot: null };
135	    case "runs": {
136	      const next = { ...state, runs: event.runs, any: event.any };
137	      const attached = attachedRun(next);
138	      // A run that went away takes its numbers with it; a run that is
139	      // still here keeps them until the next snapshot lands.
140	      return { ...next, attached, snapshot: attached === state.attached ? state.snapshot : null };
141	    }
142	    case "pin": {
143	      const next = { ...state, pinned: event.id };
144	      const attached = attachedRun(next);
145	      return { ...next, attached, snapshot: attached === state.attached ? state.snapshot : null };
146	    }
147	    case "snapshot":
148	      return { ...state, snapshot: event.snapshot };
149	    case "drove": {
150	      const flash = { ref: event.ref, ok: event.ok, ...(event.say ? { say: event.say } : {}), until: now + FLASH_MS };
151	      // A `drove` verdict is the freshest seq source: the next press
152	      // should not carry a seq gone stale while it was in flight.
153	      if (event.seq === undefined || !state.snapshot?.offer) return { ...state, flash };
154	      return { ...state, flash, snapshot: { ...state.snapshot, offer: { ...state.snapshot.offer, seq: event.seq } } };
155	    }
156	    case "tick": {
157	      const expired = state.flash !== null && state.flash.until <= now;
158	      // Controller ruling 3: a dial redraws every second while a clock is
159	      // running, so its remaining time keeps moving between snapshots. An
160	      // idle deck has nothing that changes on the tick, so it stays the
161	      // same object and nothing redraws.
162	      const running = state.snapshot?.clocks?.some((c) => c.status === "running") ?? false;
163	      if (!expired && !running) return state;
164	      return expired ? { ...state, flash: null } : { ...state };
165	    }
166	  }
167	}
168	
169	/** What a key says about the run once the deck is signed in and switched on. */
170	function held(state: DeckState): Face | null {
171	  if (state.socket !== "open") return { title: "Offline", tone: "dim" };
172	  if (state.pinned && !state.runs.some((r) => r.id === state.pinned)) return { title: "That run has ended", tone: "dim" };
173	  if (state.runs.length === 0) return state.any ? { title: "No run open", tone: "dim" } : { title: "Not synced", tone: "dim" };
174	  if (!state.attached) return { title: "Pick a run", tone: "dim" };
175	  return null;
176	}
177	
178	/** The state every key shares before any of them has something of its own to say. */
179	function common(state: DeckState): Face | null {
180	  if (state.session === "none") return { title: "Sign in", tone: "dim" };
181	  if (state.session === "expired") return { title: "Sign in again", tone: "dim" };
182	  // A key that depends on the connection says to make it first: the state
183	  // on top, the thing to do about it beneath.
184	  if (!state.on) return { title: "Not connected", tone: "dim", when: "press Connect" };
185	  return held(state);
186	}
187	
188	/** The run a deck is following, named, or nothing. */
189	function attachedName(state: DeckState): Face | null {
190	  const run = state.runs.find((r) => r.id === state.attached);
191	  if (!run) return null;
192	  return { title: run.name ?? run.packTitle ?? run.id, tone: "deck", ...(run.packTitle && run.name ? { when: run.packTitle } : {}) };
193	}
194	
195	/**
196	 * The Connect key, which reports the connection rather than the run behind it.
197	 *
198	 * It is the one key that has something to say while the deck is off, so it
199	 * skips the "Not connected" every other key stops at and names the state it
200	 * is actually in - down by choice, down by the idle timer, or on its way up.
201	 * Once the socket is open it says **Disconnect**, one press away from off -
202	 * which run that carries, if any, is the Run key's business, not this one's.
203	 */
204	export function connectFace(state: DeckState): Face {
205	  if (state.session === "none") return { title: "Sign in", tone: "dim" };
206	  if (state.session === "expired") return { title: "Sign in again", tone: "dim" };
207	  if (!state.on) return { title: "Connect", tone: "dim", when: state.idleOff ? "went idle" : undefined };
208	  if (state.socket !== "open") return { title: "Connecting", tone: "dim" };
209	  return { title: "Disconnect", tone: "deck" };
210	}
211	
212	/**
213	 * When a connection that is holding nothing should close itself.
214	 *
215	 * `since` is when it last had nothing to follow. Null means the clock is not
216	 * running at all - a deck following a live run never times out, however long
217	 * the stream goes, and a deck that is off or still dialing has nothing to
218	 * give up on.
219	 */
220	export function idleDeadline(state: DeckState, since: number): number | null {
221	  if (!state.on || state.socket !== "open" || state.runs.length > 0) return null;
222	  return since + IDLE_OFF_MS;
223	}
224	
225	function flashed(state: DeckState): Face | null {
226	  if (!state.flash || state.flash.ok) return null;
227	  return { title: state.flash.say ?? "No", tone: "refuse" };
228	}
229	
230	/** What the follow key was told about decisions. Re-exported by `actions/next.ts`. */
231	export type NextSettings = { stop?: boolean };
232	
233	/**
234	 * The decision the follow key takes for the streamer, or nothing.
235	 *
236	 * A checklist first, then a declaration with something to suggest: the two
237	 * the page publishes as presets. Placing the key and leaving *Stop at
238	 * decisions* unticked is the streamer choosing to skip the reading, which
239	 * is the rule `apps/web/src/run/handsFree.ts` asks for - a decision is
240	 * skipped only where somebody chose to skip it.
241	 */
242	function decision(offer: Offer, settings: NextSettings): Offer["presets"][number] | null {
243	  if (settings.stop) return null;
244	  const list = offer.presets.find((p) => p.kind === "checklist");
245	  if (list) return list;
246	  return offer.presets.find((p) => p.kind === "declareSubject" && (p.suggestions?.[0] ?? "") !== "") ?? null;
247	}
248	
249	/** What one press of the follow key sends, or nothing for it to send. */
250	export function nextPress(
251	  state: DeckState,
252	  settings: NextSettings,
253	): { press: "primary" } | { press: "answer"; answer: Record<string, string> } | null {
254	  const offer = state.snapshot?.offer;
255	  if (!offer) return null;
256	  if (offer.primary) return { press: "primary" };
257	  const d = decision(offer, settings);
258	  if (!d) return null;
259	  // The words the page takes for each preset, from `takePress.ts`.
260	  return d.kind === "checklist"
261	    ? { press: "answer", answer: { ticks: "all" } }
262	    : { press: "answer", answer: { subject: d.suggestions![0]! } };
263	}
264	
265	export function nextFace(state: DeckState, settings: NextSettings): Face {
266	  const c = common(state) ?? flashed(state);
267	  if (c) return c;
268	  const offer = state.snapshot?.offer;
269	  if (!offer) return { title: "Loading…", tone: "dim" };
270	  if (offer.primary) return { title: offer.primary.label, tone: "live" };
271	  // What the key would take, in the page's own words: the checklist's
272	  // button, or the name it would declare with the ask beneath it.
273	  const d = decision(offer, settings);
274	  if (d?.kind === "checklist") return { title: d.label, tone: "live" };
275	  if (d) return { title: d.suggestions![0]!, tone: "live", when: d.label };
276	  return { title: offer.needsPage ?? "Nothing to press", tone: offer.needsPage ? "refuse" : "dim" };
277	}
278	
279	export function pressFace(state: DeckState, target: PressTarget): Face {
280	  const c = common(state) ?? flashed(state);
281	  if (c) return c;
282	  const offer = state.snapshot?.offer;
283	  if (!offer) return { title: "Loading…", tone: "dim" };
284	  if (target.kind === "roll")
285	    return offer.primary?.id === "roll" ? { title: offer.primary.label, tone: "live" } : { title: "Nothing to roll", tone: "dim" };
286	  if (target.kind === "move") {
287	    const m = offer.moves.find((x) => x.id === target.id);
288	    return m ? { title: m.label, tone: "live" } : { title: "Not on offer", tone: "dim" };
289	  }
290	  const p = offer.presets.find((x) => x.kind === target.preset);
291	  return p ? { title: target.value, tone: "live", when: p.label } : { title: target.value, tone: "dim", when: "Not now" };
292	}
293	
294	/** What the dedicated Roll key says: the waiting roll, in its own words, or nothing to roll. */
295	export function rollFace(state: DeckState): Face {
296	  const c = common(state) ?? flashed(state);
297	  if (c) return c;
298	  const offer = state.snapshot?.offer;
299	  if (!offer) return { title: "Loading…", tone: "dim" };
300	  return offer.primary?.id === "roll"
301	    ? { title: offer.primary.label, tone: "live", when: "Roll" }
302	    : { title: "Nothing to roll", tone: "dim" };
303	}
304	
305	/** What the setup key says: what it applies and hands out, whether that is on offer, or nothing chosen at all. */
306	export function setupFace(state: DeckState, setup?: { id: string; title: string }): Face {
307	  const c = common(state) ?? flashed(state);
308	  if (c) return c;
309	  if (!setup) return { title: "Set up", tone: "dim" };
310	  const offer = state.snapshot?.offer;
311	  if (!offer) return { title: "Loading…", tone: "dim" };
312	  // `?? []`: an older page's offer may not name any setups at all.
313	  return (offer.setups ?? []).some((s) => s.id === setup.id)
314	    ? { title: setup.title, tone: "deck", when: "Apply setup" }
315	    : { title: setup.title, tone: "dim", when: "Not here" };
316	}
317	
318	export function undoFace(state: DeckState): Face {
319	  const c = common(state) ?? flashed(state);
320	  if (c) return c;
321	  const undo = state.snapshot?.offer?.undo;
322	  // The key says "Undo" either way: what it would take back is the run's
323	  // business, and a key too small to read it is no help at the table.
324	  return undo ? { title: "Undo", tone: "undo" } : { title: "Undo", tone: "dim" };
325	}
326	
327	/** Where the Open key points, chosen in its settings. */
328	export type OpenTarget = "run" | "guide" | "rules";
329	
330	/**
331	 * What the Open key says: the page it would put in front of the streamer.
332	 *
333	 * The guide is the one target that needs nothing - no account, no
334	 * connection, no run - so it skips the gating every other key stops at.
335	 * The run and the pack's rules both name something the deck is holding,
336	 * so they say what is missing the way the rest of the deck does.
337	 */
338	export function openFace(state: DeckState, target?: OpenTarget): Face {
339	  if (!target) return { title: "Set up", tone: "dim" };
340	  if (target === "guide") return { title: "Guide", tone: "deck", when: "in a browser" };
341	  const c = common(state);
342	  if (c) return c;
343	  return { title: target === "run" ? "Open the run" : "Rules", tone: "deck", when: "in a browser" };
344	}
345	
346	export function runFace(state: DeckState): Face {
347	  return common(state) ?? attachedName(state) ?? { title: "Pick a run", tone: "dim" };
348	}
349	
350	/** How far a clock has moved since the snapshot that reported it, in ms. */
351	function clockElapsedMs(c: NonNullable<Snapshot["clocks"]>[number], at: string, now: number): number {
352	  const since = c.status === "running" ? now - Date.parse(at) : 0;
353	  return c.elapsedMs + since;
354	}
355	
356	/** The arithmetic `stream-api.md` publishes, so a key agrees with a widget to the second. */
357	function clockText(c: NonNullable<Snapshot["clocks"]>[number], at: string, now: number): string {
358	  const elapsed = clockElapsedMs(c, at, now);
359	  const ms = c.seconds === null ? elapsed : Math.max(0, c.seconds * 1000 - elapsed);
360	  const s = Math.floor(ms / 1000);
361	  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
362	}
363	
364	export function metricFace(state: DeckState, field: MetricField, now: number): Face {
365	  const c = common(state);
366	  if (c) return c;
367	  const snap = state.snapshot;
368	  if (!snap) return { title: "Loading…", tone: "dim" };
369	  if (field === "score") return { title: snap.score?.text ?? "–", tone: "readout", when: "Score" };
370	  if (field === "unit") return { title: String(snap.unit ?? "–"), tone: "readout", when: snap.words?.unit ?? "Unit" };
371	  if (field === "latest") return { title: snap.latest?.text ?? "–", tone: "readout" };
372	  if (field === "leader") {
373	    const top = snap.standings?.[0];
374	    return top ? { title: top.name, tone: "readout", when: `${top.points} pts` } : { title: "–", tone: "dim", when: "Leader" };
375	  }
376	  if (field === "clock") {
377	    const clock = snap.clocks?.find((x) => x.status === "running") ?? snap.clocks?.[0];
378	    if (!clock || !snap.at) return { title: "–", tone: "dim", when: "Clock" };
379	    const running = clock.kind === "timer" && clock.status === "running" && clock.seconds !== null;
380	    const fraction = running ? clockElapsedMs(clock, snap.at, now) / (clock.seconds! * 1000) : undefined;
381	    return { title: clockText(clock, snap.at, now), tone: "readout", when: clock.label, ...(fraction !== undefined ? { fraction } : {}) };
382	  }
383	  if ("counter" in field) {
384	    const x = snap.counters?.find((k) => k.id === field.counter);
385	    return x ? { title: String(x.value), tone: "readout", when: x.label } : { title: "–", tone: "dim" };
386	  }
387	  const r = snap.resources?.find((k) => k.id === field.resource);
388	  return r
389	    ? { title: r.max === null ? String(r.value) : `${r.value}/${r.max}`, tone: "readout", when: r.label }
390	    : { title: "–", tone: "dim" };
391	}
