1	/**
2	 * The plugin's PNGs, and the glyphs it draws in a key's corner, from the
3	 * SVGs beside this file.
4	 *
5	 * Elgato wants PNG at two sizes for everything, and wants two different
6	 * things from one glyph: the action list takes it white on nothing at 20
7	 * square, and a key takes it in the app's colors on the app's ground at 72
8	 * square. So each glyph is drawn once, in white, and the key image is that
9	 * same glyph recolored and set on a ground here rather than drawn twice.
10	 *
11	 * `npm run icons -w streamdeck`. Nothing at run time depends on this; the
12	 * rasterizer is a devDependency of the repository, not of the plugin.
13	 */
14	import { Resvg } from "@resvg/resvg-js";
15	import { mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
16	import { dirname, join } from "node:path";
17	import { fileURLToPath } from "node:url";
18	
19	const here = dirname(fileURLToPath(import.meta.url));
20	const imgs = join(here, "..", "com.scrthq.runlog.sdPlugin", "imgs");
21	const src = join(here, "..", "src");
22	
23	/** The app's own: the ground, celadon, and kiln for the one key that takes something back. */
24	const GROUND = "#151311";
25	const ACCENT = "#9fd3b6";
26	const WARN = "#e0a94f";
27	
28	/** Both sizes of one drawing, `@2x` being the second. */
29	function write(svg, out, size) {
30	  mkdirSync(dirname(out), { recursive: true });
31	  for (const [suffix, w] of [
32	    ["", size],
33	    ["@2x", size * 2],
34	  ]) {
35	    const png = new Resvg(svg, { fitTo: { mode: "width", value: w } }).render().asPng();
36	    writeFileSync(`${out}${suffix}.png`, png);
37	  }
